import sys

def f(a, b, c, n):
    return a * n + b * n * (n.bit_length() - 1) + c * n ** 3

def main():
    a, b, c, k = map(int, sys.stdin.read().split())
    lo, hi = 1, 10 ** 6 + 1
    while lo < hi:
        mid = (lo + hi) // 2
        if f(a, b, c, mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    print(lo if lo <= 10 ** 6 and f(a, b, c, lo) == k else 0)

